<script setup lang="ts">
import { ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import AppWindowDialog from '@/components/common/AppWindowDialog.vue'
import { fetchAssemblyCandidates } from '@/api/finishedReceipts'
import type { AssemblyCandidate } from '@/types/finishedReceipts'
const visible=defineModel<boolean>({default:false}),router=useRouter(),q=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),rows=ref<AssemblyCandidate[]>([])
async function load(){loading.value=true;error.value='';try{const data=await fetchAssemblyCandidates({q:q.value,page:page.value,page_size:20});rows.value=data.items;total.value=data.total}catch{error.value='装配计划读取失败，请重试。';rows.value=[]}finally{loading.value=false}}
watch(visible,v=>{if(v){page.value=1;void load()}})
function select(row:AssemblyCandidate){visible.value=false;void router.push({name:'assembly-finished-receipt',query:{schedule_product_id:row.id}})}
</script>
<template><AppWindowDialog v-model="visible" title="选择成品入库订单" :width="1180" :height="660" class="fg-window" destroy-on-close><div class="fg-picker"><div class="fg-filters"><ElInput v-model="q" placeholder="搜索计划、生产单号或品名" @keyup.enter="page=1;load()"/><ElButton @click="page=1;load()">查询</ElButton></div><ElAlert v-if="error" :title="error" type="error"/><div class="fg-table-card" v-loading="loading"><div class="fg-table-scroll"><table class="fg-table compact"><colgroup><col style="width:145px"><col style="width:110px"><col style="width:160px"><col style="width:145px"><col><col style="width:90px"><col style="width:90px"><col style="width:60px"><col style="width:75px"></colgroup><thead><tr><th>装配计划</th><th>生产单号</th><th>品号</th><th>品名</th><th>规格</th><th class="num">订单量</th><th class="num">已入库</th><th>单位</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.schedule_number}}</td><td>{{r.task_number}}</td><td>{{r.product_number}}</td><td :title="r.product_name">{{r.product_name}}</td><td :title="r.specification">{{r.specification}}</td><td class="num">{{r.order_quantity.toLocaleString('zh-CN')}}</td><td class="num">{{r.received_total.toLocaleString('zh-CN')}}</td><td>{{r.unit_name}}</td><td><ElButton link type="primary" @click="select(r)">选择</ElButton></td></tr></tbody></table><div v-if="!loading&&!rows.length" class="fg-empty">暂无有权限办理的装配计划</div></div></div></div><template #footer><ElPagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/><ElButton @click="visible=false">取消</ElButton></template></AppWindowDialog></template>
